{
  "id": "R1",
  "summary_ko": "벨트 버클의 모양이 변함.",
  "claims": [
    {
      "id": "R1.S1",
      "evidence": "Belt buckle changes shape.",
      "symptom_ko": "벨트 버클의 형태가 변함",
      "is_anomaly": true,
      "specificity": "specific",
      "target_evidence": "Belt buckle",
      "explicit_detail_evidence": [
        "changes shape"
      ],
      "missing_details_ko": ""
    }
  ]
}

{
  "id": "R2",
  "summary_ko": "손의 형태가 어색하고 부자연스러움.",
  "claims": [
    {
      "id": "R2.S1",
      "evidence": "Shape of hand is awkward, unnatural.",
      "symptom_ko": "손의 형태가 어색하고 부자연스러움",
      "is_anomaly": true,
      "specificity": "broad",
      "target_evidence": "Shape of hand",
      "explicit_detail_evidence": [],
      "missing_details_ko": "손 형태가 구체적으로 어떻게 어색하고 부자연스러운지(손가락 수, 뒤틀림, 기형 등) 명시되지 않음"
    }
  ]
}

{
  "id": "R3",
  "summary_ko": "소매가 더 이상 팔 위에 있는 것처럼 보이지 않고, 마치 팔 자체인 것처럼 같은 층위에서 나타남.",
  "claims": [
    {
      "id": "R3.S1",
      "evidence": "Sleeves no longer appear as on the arm, but at the same level, as if they are the arm.",
      "symptom_ko": "소매가 팔 위에 입혀진 형태가 아니라 팔과 동일한 층위에서 팔 자체처럼 보임.",
      "is_anomaly": true,
      "specificity": "specific",
      "target_evidence": "Sleeves",
      "explicit_detail_evidence": [
        "no longer appear as on the arm",
        "at the same level, as if they are the arm"
      ],
      "missing_details_ko": ""
    }
  ]
}

{
  "id": "R4",
  "summary_ko": "남자가 현실에서 일어날 수 없고 물리 법칙을 거스르는 방식으로 점프하며, 마치 영상에 슬로우 모션 필터를 적용한 것처럼 보임.",
  "claims": [
    {
      "id": "R4.S1",
      "evidence": "The man is jumping in a way that wouldn't happen in real life and defies the law of physics as some sort of slow motion filter was put on this video",
      "symptom_ko": "남자가 물리 법칙을 거스르고 비현실적인 방식으로 점프하며 슬로우 모션 필터를 적용한 듯이 보임",
      "is_anomaly": true,
      "specificity": "specific",
      "target_evidence": "The man",
      "explicit_detail_evidence": [
        "jumping in a way that wouldn't happen in real life and defies the law of physics",
        "slow motion filter was put on this video"
      ],
      "missing_details_ko": ""
    }
  ]
}

{
  "id": "R5",
  "summary_ko": "사람이 정지 상태에서 실제로는 불가능할 정도로 너무 높이 점프하여 물리 법칙을 위배함",
  "claims": [
    {
      "id": "R5.S1",
      "evidence": "The person jumps way higher from a stand still position then anyone could in real life so again it defies the law of physics",
      "symptom_ko": "사람이 제자리 정지 상태에서 비현실적으로 너무 높이 점프함",
      "is_anomaly": true,
      "specificity": "specific",
      "target_evidence": "The person",
      "explicit_detail_evidence": [
        "jumps way higher from a stand still position then anyone could in real life"
      ],
      "missing_details_ko": ""
    }
  ]
}

{
  "pairs": [
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "target_relation": "uncertain",
      "reference_claim_ids": ["R2.S1"],
      "reference_evidence": "",
      "candidate_evidence": "",
      "basis": "insufficient",
      "reason_ko": "R2는 손의 형태가 어색하고 부자연스럽다고 기술하고, C1은 공중에 뜬 인물의 비율 변형 및 사지(limb) 동역학 이상을 기술합니다. 사지 변형에 손이 포함될 가능성이 있으나, C1에서 손 자체의 형태 이상을 명시하지 않아 동일한 결함인지 명확히 판단하기에 텍스트 정보가 불충분합니다."
    }
  ]
}

